import data from '../content/posts.json';
import pingData from '../content/ping.json';

export type Mode = 'research' | 'life';

export type Post = {
  slug: string;
  title: string;
  subtitle: string;
  date: string;
  url: string;
  publication: string;
  mode: Mode;
  cover: string | null;
  readingMinutes: number;
  html: string;
};

// Generated by `npm run sync`; newest first.
export const posts = data as Post[];

// Posts published elsewhere (not on Substack). These link out instead of getting their own page.
export type ExternalPost = {slug: string; title: string; date: string; url: string; publication: string; mode: Mode; external: true};
const elsewhere: ExternalPost[] = [
  {
    slug: 'more-than-a-lab',
    title: 'More than a lab: My Experience at Precog',
    date: '2026-08-03',
    url: 'https://www.linkedin.com/pulse/more-than-lab-my-experience-precog-vaishnavi-shivkumar-gixvc/',
    publication: 'LinkedIn',
    mode: 'research',
    external: true,
  },
];

// Everything to list on the site, newest first.
export type ListedPost = Post | ExternalPost;
export const writing: ListedPost[] = [...posts, ...elsewhere].sort((a, b) => b.date.localeCompare(a.date));

// Articles for Ping!, IIIT Hyderabad's student publication. These link out to pingiiit.org.
export type PingDesign = {title: string; url: string; image: string};
export type PingArticle = {title: string; date: string; url: string; excerpt: string; image?: string; designs?: PingDesign[]};
export const ping = pingData as PingArticle[];
export const pingAuthorUrl = 'https://pingiiit.org/author/vaishnavi-shivkumar/';

export const formatDate = (iso: string) =>
  new Date(iso + 'T00:00:00Z').toLocaleDateString('en-GB', {day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC'});
